    unsafe result.pointee = SIMD<Int8>(
        raw: HighwayReference.Nothrow.vectorClampingInAnyOrderRoundingShiftedRightByI16ToI8(
            a.raw,
            b.raw,
            8
        )
    )
}
#endif
